#pragma once
#include <Arduino.h>

// The entry for a date in a language: "Martin, Maroš" or, on a public holiday
// without a name, the holiday ("Svátek práce") with *holiday = true.
// ascii = without diacritics, for the built-in pixel font.
// false = nothing to show (English, or no entry).
bool NameDay_Get(uint8_t lang, int month, int day, bool ascii,
                 char* out, size_t cap, bool* holiday);

// Drop the last ", name" from a list. false when only one name is left.
bool NameDay_DropLast(char* list);
